\set ON_ERROR_STOP on
begin;
do $$
declare a uuid:='f0950000-0000-4000-8000-000000000001';p uuid:='f0950000-0000-4000-8000-000000000002';q uuid:='f0950000-0000-4000-8000-000000000003';v jsonb;d jsonb;h jsonb;catalog jsonb;other jsonb;ref text;pid uuid;qid uuid;second_id uuid;notice_id text;second jsonb;town_version bigint;
begin
 insert into auth.users(id,email,is_anonymous,email_confirmed_at) values(a,'merchant-admin@example.test',false,now()),(p,'merchant-owner@example.test',false,now()),(q,'merchant-other@example.test',false,now());insert into private.game_admins values(a);

 select data into h from private.game_world_edits where world='town';
 select jsonb_set(h,'{objects}',jsonb_object_agg(key,case when key='portal' then value else 'null'::jsonb end)) into h from jsonb_each(h->'objects');
 h:=jsonb_set(h,'{buildings}','{"building-900":{"x":19,"z":18,"rotation":1,"style":"plot","name":"East lot"},"building-901":{"x":-19,"z":18,"rotation":0,"style":"plot","name":"West lot"},"building-902":{"x":19,"z":-18,"rotation":0,"style":"plot","name":"North lot"}}');
 perform set_config('request.jwt.claim.sub',a::text,true);set local role authenticated;
 other:=public.mmo_world_editor('read','town');perform public.mmo_world_editor('save','town',h,(other->>'version')::bigint);reset role;
 perform set_config('request.jwt.claim.sub',p::text,true);set local role authenticated;
 v:=public.mmo_world_editor('merchant_read');
 if v->'application'<>'null'::jsonb or v?'applications' then raise exception 'Application privacy failed';end if;
 d:='{"fullName":"Seller One","email":"seller@example.test","phone":"0123456789","address":"Test address","shopName":"Flower Store","description":"Flowers and gifts","plot":"building-900"}';

 begin perform public.mmo_world_editor('merchant_submit','town',jsonb_set(d,'{plot}','"h2h"'),0);raise exception 'Application accepted a non-empty plot';exception when raise_exception then if sqlerrm='Application accepted a non-empty plot' then raise;end if;end;
 v:=public.mmo_world_editor('merchant_submit','town',d,0);
 pid:=(v->'application'->>'id')::uuid;
 if v->'application'->'details'->>'plot' is distinct from 'building-900' then raise exception 'Requested plot was not recorded';end if;
 if v->'application'->>'status'<>'pending' then raise exception 'Submit failed';end if;
 begin perform public.mmo_world_editor('merchant_review',pid::text,'{"status":"approved","plot":"building-900"}',1);raise exception 'Player self-approved';exception when insufficient_privilege then null;end;
 begin perform public.mmo_world_editor('shop_save','h2h','{"products":[]}',0);raise exception 'Player edits H2H';exception when insufficient_privilege then null;end;
 begin perform 1 from private.game_merchant_applications;raise exception 'Player reads private table';exception when insufficient_privilege then null;end;
 reset role;perform set_config('request.jwt.claim.sub',q::text,true);set local role authenticated;
 h:=public.mmo_world_editor('merchant_read');if h->'application'<>'null'::jsonb or h?'applications' then raise exception 'Other player sees PII';end if;
 reset role;perform set_config('request.jwt.claim.sub',a::text,true);set local role authenticated;
 h:=public.mmo_world_editor('merchant_review',pid::text,'{"status":"more_info","note":"Please add your contact address details"}',(v->'application'->>'version')::bigint);
 reset role;perform set_config('request.jwt.claim.sub',p::text,true);set local role authenticated;
 v:=public.mmo_world_editor('merchant_read');
 if v->'application'->>'note' not like 'Please add%' then raise exception 'Feedback missing';end if;
 v:=public.mmo_world_editor('merchant_submit','town',d,(v->'application'->>'version')::bigint);
 reset role;
 select data into h from private.game_world_edits where world='town';
 select jsonb_set(h,'{objects}',jsonb_object_agg(key,case when key='portal' then value else 'null'::jsonb end)) into h from jsonb_each(h->'objects');
 h:=jsonb_set(h,'{buildings}','{"building-900":{"x":19,"z":18,"rotation":1,"style":"plot","name":"East lot"},"building-901":{"x":-19,"z":18,"rotation":0,"style":"plot","name":"West lot"},"building-902":{"x":19,"z":-18,"rotation":0,"style":"plot","name":"North lot"}}');
 perform set_config('request.jwt.claim.sub',a::text,true);set local role authenticated;
 other:=public.mmo_world_editor('read','town');perform public.mmo_world_editor('save','town',h,(other->>'version')::bigint);
 h:=public.mmo_world_editor('merchant_review',pid::text,'{"status":"approved","plot":"building-900","note":"Welcome"}',(v->'application'->>'version')::bigint);
 begin perform public.mmo_world_editor('merchant_review',pid::text,'{"status":"suspended","note":"stale"}',(v->'application'->>'version')::bigint);raise exception 'Stale review accepted';exception when serialization_failure then null;end;
 other:=public.mmo_world_editor('read','town');if other->'data'->'buildings'->'building-900'->>'shopType'<>'website' then raise exception 'Plot not converted to shop';end if;
 reset role;perform set_config('request.jwt.claim.sub',p::text,true);set local role authenticated;
 catalog:=public.mmo_world_editor('shop_read','building-900');
 if catalog->>'canManage' is distinct from 'true' then raise exception 'Approved owner lacks manager access';end if;
 catalog:=public.mmo_world_editor('shop_save','building-900','{"products":[{"id":"new-rose","kind":"website","reference":"","name":"Rollback merchant rose","image":"/game/items/carrot.svg","description":"","category":"Flowers","active":true,"buyPrice":1000,"sellPrice":null,"originalPrice":1000}]}',(catalog->>'version')::bigint);
 ref:=catalog->'products'->0->>'reference';
 begin perform public.mmo_world_editor('save','town',other->'data',(other->>'version')::bigint);raise exception 'Owner gained town editor';exception when insufficient_privilege then null;end;
 reset role;perform set_config('request.jwt.claim.sub',q::text,true);set local role authenticated;
 v:=public.mmo_world_editor('merchant_submit','town',jsonb_set(jsonb_set(d,'{shopName}','"Other shop"'),'{plot}','"building-901"'),0);
 qid:=(v->'application'->>'id')::uuid;
 other:=public.mmo_world_editor('shop_read','building-900');if other->>'canManage' is distinct from 'false' then raise exception 'Unrelated player has manager access';end if;
 begin perform public.mmo_world_editor('shop_save','building-900',catalog,(catalog->>'version')::bigint);raise exception 'Other player edits owned shop';exception when insufficient_privilege then null;end;
 reset role;perform set_config('request.jwt.claim.sub',a::text,true);set local role authenticated;
 begin perform public.mmo_world_editor('merchant_review',qid::text,'{"status":"approved","plot":"building-900"}',(v->'application'->>'version')::bigint);raise exception 'Occupied plot assigned twice';exception when raise_exception then if sqlerrm='Occupied plot assigned twice' then raise;end if;end;
 h:=public.mmo_world_editor('merchant_review',pid::text,'{"status":"suspended","note":"Review required"}',(h->'application'->>'version')::bigint);
 reset role;
 if exists(select 1 from public.products where id=ref::bigint and active) then raise exception 'Suspended products still active';end if;
 perform set_config('request.jwt.claim.sub',p::text,true);set local role authenticated;
 begin perform public.mmo_world_editor('shop_save','building-900',catalog,(catalog->>'version')::bigint);raise exception 'Suspended owner edits';exception when insufficient_privilege then null;end;
 begin perform public.mmo_world_editor('shop_read','building-900');raise exception 'Suspended shop open';exception when raise_exception then if sqlerrm='Suspended shop open' then raise;end if;end;
 reset role;perform set_config('request.jwt.claim.sub',a::text,true);set local role authenticated;
 h:=public.mmo_world_editor('merchant_review',pid::text,'{"status":"approved","note":"Reinstated"}',(h->'application'->>'version')::bigint);
 reset role;
 if not exists(select 1 from public.products where id=ref::bigint and active) then raise exception 'Reinstatement failed to restore product';end if;
 perform set_config('request.jwt.claim.sub',a::text,true);set local role authenticated;
 v:=public.mmo_world_editor('merchant_review',qid::text,'{"status":"rejected","note":"Not eligible"}',(v->'application'->>'version')::bigint);
 if v->'application'->>'status'<>'rejected' then raise exception 'Rejection failed';end if;
 reset role;
 if not exists(select 1 from private.game_merchant_audit where applicant=p and status='approved') then raise exception 'Review not audited';end if;

 -- One owner may operate several independently approved shops.
 perform set_config('request.jwt.claim.sub',p::text,true);set local role authenticated;
 second:=public.mmo_world_editor('merchant_submit','town',jsonb_set(jsonb_set(d,'{shopName}','"Second shop"'),'{plot}','"building-901"'),0);
 second_id:=(second->'application'->>'id')::uuid;
 if second_id=pid or jsonb_array_length(second->'ownApplications')<>2 then raise exception 'Multiple applications not independent';end if;
 begin perform public.mmo_world_editor('merchant_submit','town',jsonb_set(d,'{plot}','"building-901"'),0);raise exception 'Duplicate pending application accepted';exception when raise_exception then if sqlerrm='Duplicate pending application accepted' then raise;end if;end;
 reset role;perform set_config('request.jwt.claim.sub',q::text,true);set local role authenticated;
 begin perform public.mmo_world_editor('merchant_submit',pid::text,d,0);raise exception 'Other player updated application';exception when insufficient_privilege then null;end;
 reset role;perform set_config('request.jwt.claim.sub',a::text,true);set local role authenticated;
 second:=public.mmo_world_editor('merchant_review',second_id::text,'{"status":"approved","plot":"building-901"}',(second->'application'->>'version')::bigint);
 begin perform public.mmo_world_editor('merchant_review',pid::text,'{"status":"closed"}',(h->'application'->>'version')::bigint);raise exception 'Closure without reason accepted';exception when raise_exception then if sqlerrm='Closure without reason accepted' then raise;end if;end;
 reset role;select version into town_version from private.game_world_edits where world='town';set local role authenticated;
 h:=public.mmo_world_editor('merchant_review',pid::text,'{"status":"closed","note":"Shop closed for policy review"}',(h->'application'->>'version')::bigint);
 reset role;
 if exists(select 1 from public.products where id=ref::bigint and active) then raise exception 'Closed products active';end if;
 if (select data->'buildings'->'building-900'->>'style' from private.game_world_edits where world='town') is distinct from 'plot' then raise exception 'Closed shop did not become plot';end if;
 if not (select data->'buildings'->'building-900' @> '{"x":19,"z":18,"rotation":1,"name":"Empty shop plot"}' from private.game_world_edits where world='town') then raise exception 'Empty plot lost its location or rotation';end if;
 if exists(select 1 from private.game_town_collisions() where kind='box' and x=19 and z=18) then raise exception 'Closed storefront collision survived';end if;
 if (select count(*) from private.game_merchant_notifications where application_id=pid and status='closed' and audience='player')<>1 then raise exception 'Closure created duplicate owner notifications';end if;
 if (select version from private.game_world_edits where world='town')<=town_version then raise exception 'Closure did not invalidate stale Town editors';end if;
 if (select data->'buildings'->'building-900' from private.game_world_edits where world='town') @> '{"shopType":"website"}' then raise exception 'Plot retained shop type';end if;
 if h->'application'->>'note'<>'Shop closed for policy review' or h->'application'->'shop_id'<>'null'::jsonb then raise exception 'Closure reason or release was overwritten by Town triggers';end if;
 if not exists(select 1 from jsonb_array_elements(h->'plots') e where e->>'id'='building-900') then raise exception 'Released plot not offered for applications';end if;
 if exists(select 1 from private.game_shop_catalog where shop='building-900') then raise exception 'Closed shop catalogue binding retained';end if;
 if not private.game_merchant_owner(p,'building-901') or private.game_merchant_owner(p,'building-900') then raise exception 'Closure affected wrong shop';end if;
 perform set_config('request.jwt.claim.sub',p::text,true);set local role authenticated;
 v:=public.mmo_world_editor('merchant_notices');
 if v?'applications' or v?'ownApplications' then raise exception 'Notice feed leaked application details';end if;
 select e->>'id' into notice_id from jsonb_array_elements(v->'notifications') e where e->>'status'='closed';
 if notice_id is null or (v->>'unread')::int<1 then raise exception 'Closure notification missing';end if;
 begin perform public.mmo_world_editor('shop_save','building-900',catalog,(catalog->>'version')::bigint);raise exception 'Closed owner edits';exception when insufficient_privilege then null;when raise_exception then if sqlerrm='Closed owner edits' then raise;end if;end;
 other:=public.mmo_world_editor('shop_read','building-901');if other->>'canManage'<>'true' then raise exception 'Other shop no longer manageable';end if;
 reset role;perform set_config('request.jwt.claim.sub',q::text,true);set local role authenticated;
 v:=public.mmo_world_editor('merchant_ack',notice_id);
 if v->'ownApplications' @> jsonb_build_array(jsonb_build_object('id',pid)) then raise exception 'Other owner application leaked';end if;
 reset role;
 if exists(select 1 from private.game_merchant_notifications where id=notice_id::uuid and read_at is not null) then raise exception 'Other user acknowledged private notice';end if;
 perform set_config('request.jwt.claim.sub',p::text,true);set local role authenticated;
 perform public.mmo_world_editor('merchant_ack',notice_id);
 other:=public.mmo_world_editor('merchant_submit','town',jsonb_set(jsonb_set(d,'{shopName}','"Third shop application"'),'{plot}','"building-902"'),0);
 if jsonb_array_length(other->'ownApplications')<>3 or other->'application'->>'status'<>'pending' then raise exception 'New shop application after closure failed';end if;
 -- Former owner may apply again, but released plots are available to other players too.
 v:=public.mmo_world_editor('merchant_submit',pid::text,d,(h->'application'->>'version')::bigint);
 if v->'application'->>'status'<>'pending' then raise exception 'Reopening request failed';end if;
 begin perform public.mmo_world_editor('shop_read','building-900');raise exception 'Reapplication reopened prematurely';exception when raise_exception then if sqlerrm='Reapplication reopened prematurely' then raise;end if;end;
 reset role;perform set_config('request.jwt.claim.sub',q::text,true);set local role authenticated;
 other:=public.mmo_world_editor('merchant_read');
 other:=public.mmo_world_editor('merchant_submit',qid::text,d,(other->'application'->>'version')::bigint);
 reset role;perform set_config('request.jwt.claim.sub',a::text,true);set local role authenticated;
 other:=public.mmo_world_editor('merchant_review',qid::text,'{"status":"approved","plot":"building-900","note":"New tenant"}',(other->'application'->>'version')::bigint);
 begin perform public.mmo_world_editor('merchant_review',pid::text,'{"status":"approved","plot":"building-900"}',(v->'application'->>'version')::bigint);raise exception 'Former owner reclaimed occupied plot';exception when raise_exception then if sqlerrm='Former owner reclaimed occupied plot' then raise;end if;end;
 h:=public.mmo_world_editor('merchant_review',pid::text,'{"status":"approved","plot":"building-902","note":"Approved on another plot"}',(v->'application'->>'version')::bigint);
 reset role;
 if exists(select 1 from public.products where id=ref::bigint and active) then raise exception 'New tenant restored previous owner products';end if;
 if not exists(select 1 from public.products where id=ref::bigint) then raise exception 'Closure deleted website product records';end if;
 if not private.game_merchant_owner(q,'building-900') or private.game_merchant_owner(p,'building-900') then raise exception 'Released plot ownership not transferred correctly';end if;
 perform set_config('request.jwt.claim.sub',q::text,true);set local role authenticated;
 other:=public.mmo_world_editor('shop_read','building-900');
 if jsonb_array_length(other->'products')<>0 then raise exception 'New tenant inherited former shop catalogue';end if;
 reset role;
 if not exists(select 1 from private.game_merchant_notifications where id=notice_id::uuid and read_at is not null) then raise exception 'Acknowledgement not persisted';end if;
 -- Removing the assigned building revokes ownership and keeps its website records.
 update private.game_world_edits set data=jsonb_set(data,'{buildings}','{}') where world='town';
 if exists(select 1 from private.game_merchant_applications where applicant=p and status='approved') then raise exception 'Removed-shop ownership survived';end if;
end$$;
rollback;
